function Get-AI5ClaudeApiCredentialStatus {Get-AI5ApiNodeStatus 'claude_api'}
function New-AI5ClaudeApiRequest {param($Task,[string]$Model='claude-sonnet');if(!$Task.TASK_ID-or!$Task.CORRELATION_ID){throw 'zero_task_identity_required'};[ordered]@{provider='anthropic';node='claude_api';model=$Model;task_id=$Task.TASK_ID;correlation_id=$Task.CORRELATION_ID;purpose=$Task.PURPOSE;canonical_repo=$Task.CANONICAL_REPO;canonical_branch=$Task.CANONICAL_BRANCH;allowed_actions=@($Task.ALLOWED_ACTIONS);prohibited_actions=@($Task.PROHIBITED_ACTIONS);expected_result=$Task.EXPECTED_RESULT}}
function Invoke-AI5ClaudeApiAdapter {param($Task,[scriptblock]$Transport=$null,[string]$ApiKey='',[string]$Model='claude-sonnet-4-20250514')
  if(!$ApiKey){$ApiKey=[Environment]::GetEnvironmentVariable('ANTHROPIC_API_KEY')};if(!$ApiKey){$ApiKey=[Environment]::GetEnvironmentVariable('CLAUDE_API_KEY')}
  if(!$ApiKey-and!$Transport){return [ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='claude_api';STATUS='WAITING_OWNER_AUTH';SUMMARY='Claude API credential is not configured';EVIDENCE=@();ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}
  $request=New-AI5ClaudeApiRequest $Task $Model;$payload=[ordered]@{model=$Model;max_tokens=1200;messages=@([ordered]@{role='user';content=($request|ConvertTo-Json -Depth 12)})};$headers=@{'x-api-key'=$ApiKey;'anthropic-version'='2023-06-01';'content-type'='application/json'}
  try{$response=if($Transport){&$Transport 'https://api.anthropic.com/v1/messages' $headers $payload}else{Invoke-RestMethod -Method Post -Uri 'https://api.anthropic.com/v1/messages' -Headers $headers -Body ($payload|ConvertTo-Json -Depth 12) -TimeoutSec 120};$text=[string](@($response.content|Where-Object{$_.type-eq'text'}|Select-Object -First 1).text);if(!$text){throw 'empty_api_result'};[ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='claude_api';STATUS='PASS';SUMMARY=$text;EVIDENCE=@('anthropic_messages_api');ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}catch{[ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='claude_api';STATUS='FAIL';SUMMARY='Claude API request failed';EVIDENCE=@('transport_failure_redacted');ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}
}
